import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.when;

public class BasicDeserializerFactory_createTreeDeserializer_TriageGen0Test {

    private BasicDeserializerFactory factory;
    private DeserializationConfig config;
    private JavaType javaType;
    private BeanDescription beanDesc;

    /**
     * A concrete implementation of BasicDeserializerFactory to allow testing 
     * protected methods and constructor access.
     */
    private static class TestBasicDeserializerFactory extends BasicDeserializerFactory {
        public TestBasicDeserializerFactory(DeserializerFactoryConfig config) {
            super(config);
        }

        @Override
        protected DeserializerFactory withConfig(DeserializerFactoryConfig config) {
            return this;
        }
    }

    @Before
    public void setUp() {
        factory = spy(new TestBasicDeserializerFactory(new DeserializerFactoryConfig()));
        config = Mockito.mock(DeserializationConfig.class);
        javaType = Mockito.mock(JavaType.class);
        beanDesc = Mockito.mock(BeanDescription.class);
    }

    @Test
    public void testCreateTreeDeserializer_ReturnsCustomDeserializer() throws JsonMappingException {
        // Arrange
        Class<? extends JsonNode> nodeClass = ObjectNode.class;
        when(javaType.getRawClass()).thenReturn(nodeClass);

        JsonDeserializer<?> customDeserializer = Mockito.mock(JsonDeserializer.class);
        // Mock the internal call to _findCustomTreeNodeDeserializer
        doReturn(customDeserializer).when(factory)._findCustomTreeNodeDeserializer(eq(nodeClass), eq(config), eq(beanDesc));

        // Act
        JsonDeserializer<?> result = factory.createTreeDeserializer(config, javaType, beanDesc);

        // Assert
        assertEquals("Should return the custom deserializer if found", customDeserializer, result);
    }

    @Test
    public void testCreateTreeDeserializer_ReturnsDefaultDeserializer() throws JsonMappingException {
        // Arrange
        Class<? extends JsonNode> nodeClass = ObjectNode.class;
        when(javaType.getRawClass()).thenReturn(nodeClass);

        // Mock the internal call to return null, triggering the default fallback
        doReturn(null).when(factory)._findCustomTreeNodeDeserializer(eq(nodeClass), eq(config), eq(beanDesc));

        // Act
        JsonDeserializer<?> result = factory.createTreeDeserializer(config, javaType, beanDesc);

        // Assert
        assertNotNull("Result should not be null", result);
        // JsonNodeDeserializer.getDeserializer(ObjectNode.class) returns an instance of JsonNodeDeserializer
        // We check if it's the correct type/non-null.
        assertEquals(JsonNodeDeserializer.class, result.getClass());
    }

    @Test(expected = JsonMappingException.class)
    public void testCreateTreeDeserializer_ThrowsExceptionWhenCustomFinderThrows() throws JsonMappingException {
        // Arrange
        Class<? extends JsonNode> nodeClass = ObjectNode.class;
        when(javaType.getRawClass()).thenReturn(nodeClass);

        doThrow(new JsonMappingException(null, "Custom error"))
            .when(factory)._findCustomTreeNodeDeserializer(eq(nodeClass), eq(config), eq(beanDesc));

        // Act
        factory.createTreeDeserializer(config, javaType, beanDesc);

        // Assert handled by expected exception
    }

    @Test(expected = ClassCastException.class)
    public void testCreateTreeDeserializer_ThrowsClassCastExceptionWhenNotJsonNode() throws JsonMappingException {
        // Arrange
        // Mocking a type that is NOT a subclass of JsonNode to trigger the (Class<? extends JsonNode>) cast failure
        when(javaType.getRawClass()).thenReturn(String.class);

        // Act
        factory.createTreeDeserializer(config, javaType, beanDesc);
    }
}
